import {loadingState,loadFailure} from './loading-state.js';
import {proseMarkdown,enhanceMarkdown} from './rich-text.js';
import {libraryIcon} from './agent-appearance.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories={decision:'Decisions & reasons',attempt:'Attempts & lessons',file:'Relevant files',question:'Open questions',next:'Next steps'};
const options=(items,selected)=>Object.entries(items).map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${label}</option>`).join('');
const time=value=>value?new Date(value).toLocaleString():'';

export class MemoryView {
  constructor(host,{api,registry,onClose,onExpand,expanded=false}){
    Object.assign(this,{host,api,registry,onClose,onExpand,expanded});this.mode='notebook';this.generation=0;this.notebookContacts=registry.contacts.filter(c=>!c.external);this.agentId=this.notebookContacts[0]?.id||'';this.entries=[];
    host.classList.add('memory-drawer');
    host.innerHTML=`<div class="drawer-heading"><h2>${libraryIcon('notebook-pen',20)} Memory</h2><div class="drawer-heading-actions"><button type="button" data-memory="expand" aria-label="${expanded?'Restore memory panel':'Expand memory'}">${libraryIcon(expanded?'minimize-2':'maximize-2',16)}</button><button type="button" data-memory="close" aria-label="Close memory">×</button></div></div><nav class="memory-tabs" aria-label="Memory view"><button type="button" data-memory-tab="notebook">Agent notebooks</button><button type="button" data-memory-tab="shared">Shared decisions</button><button type="button" data-memory-tab="search">Search</button></nav><div class="memory-body"></div><p class="memory-feedback" role="status" aria-live="polite"></p>`;
    this.click=e=>this.handleClick(e).catch(error=>this.feedback(error.message,true));
    this.change=e=>{if(e.target.name==='notebookAgent'){this.agentId=e.target.value;delete this.historyRevision;this.load().catch(error=>this.feedback(error.message,true));}if(e.target.name==='notebookRevision')this.history(Number(e.target.value)).catch(error=>this.feedback(error.message,true));};
    this.submit=e=>{if(!e.target.matches('[data-memory-form]'))return;e.preventDefault();this.handleSubmit(e.target).catch(error=>this.feedback(error.message,true));};
    host.addEventListener('click',this.click);host.addEventListener('change',this.change);host.addEventListener('submit',this.submit);this.load().catch(error=>this.feedback(error.message,true));
  }
  setExpanded(expanded){this.expanded=expanded;const b=this.host.querySelector('[data-memory="expand"]');if(b){b.innerHTML=libraryIcon(expanded?'minimize-2':'maximize-2',16);b.setAttribute('aria-label',expanded?'Restore memory panel':'Expand memory');}}
  feedback(text,error=false){const notes=this.host.querySelector('.memory-notes[aria-busy="true"]');if(error&&notes){notes.removeAttribute('aria-busy');notes.innerHTML=loadFailure('Notebook couldn’t load',{detail:text,retry:'data-memory="refresh"'});return;}const el=this.host.querySelector('.memory-feedback');if(el){el.textContent=text;el.classList.toggle('form-error',error);}}
  agentSelect(){return `<label class="memory-agent-label">Agent<select name="notebookAgent" aria-label="Notebook agent">${this.notebookContacts.map(c=>`<option value="${esc(c.id)}" ${c.id===this.agentId?'selected':''}>${esc(c.role)}</option>`).join('')}</select></label>`;}
  renderHeader(){for(const b of this.host.querySelectorAll('[data-memory-tab]'))b.setAttribute('aria-pressed',String(b.dataset.memoryTab===this.mode));this.feedback('');}
  async load(){
    const generation=++this.generation;this.renderHeader();const body=this.host.querySelector('.memory-body');
    if(this.mode==='shared'){body.innerHTML=`<p class="memory-intro">Accepted decisions and findings shared across this project. Agents access these through shared memory; private working notes stay in their notebooks.</p>${this.registry.memory.map(n=>`<article class="memory-note"><h3>${esc(n.key)}</h3><div class="markdown document-markdown">${proseMarkdown(n.text)}</div><footer>${esc(n.author)} · Revision ${n.revision}</footer></article>`).join('')||'<div class="memory-empty">No shared decisions yet. An agent can publish a project note after the team agrees on it.</div>'}`;enhanceMarkdown(body);return;}
    if(this.mode==='search'){body.innerHTML=`<p class="memory-intro">Find decisions, task evidence and earlier context without reopening entire histories. Use your configured ranking, or keep this search local. Only this agent’s accessible sources are searched.</p>${this.agentSelect()}<form data-memory-form="search" class="memory-search"><label for="memory-query">What do you need to recall?</label><div><input id="memory-query" name="query" required minlength="2" maxlength="200" placeholder="A task, file, decision or failed approach"><button class="primary" type="submit">Search</button></div><label for="memory-scope">Look in</label><select id="memory-scope" name="scope">${options({all:'All accessible memory',notebook:'This notebook',shared:'Shared decisions',tasks:'Task briefs',archives:'Earlier context'},'all')}</select><label>Ranking<select name="ranking"><option value="semantic">Use configured ranking</option><option value="local">Local only · no AI call</option></select></label></form><div class="memory-results"></div>`;return;}
    if(!this.agentId){body.innerHTML='<div class="memory-empty">Create an agent to give it a persistent working notebook.</div>';return;}
    body.innerHTML=`<p class="memory-intro">A small working notebook for each agent. It survives session and provider changes. Visible to this agent and you; other agents use shared decisions.</p>${this.agentSelect()}<div class="memory-notes" aria-busy="true">${loadingState('Loading notebook',{detail:'Reading this agent’s saved working notes.'})}</div>`;
    const book=await this.api('notebook?task='+encodeURIComponent(this.agentId));if(generation!==this.generation)return;
    this.book=book;this.entries=book.entries;this.renderNotebook();
  }
  renderNotebook(){
    const el=this.host.querySelector('.memory-notes');if(!el)return;el.removeAttribute('aria-busy');const revision=this.historyRevision??this.book.revision,historical=this.historyRevision!==undefined;
    el.innerHTML=`<div class="memory-toolbar"><span>Revision ${revision} · ${this.entries.filter(n=>n.status==='active').length} active notes${historical?' · History':''}</span><div><button type="button" data-memory="refresh">${historical?'Return to current':'Reload'}</button>${!historical?'<button type="button" class="primary" data-memory="add">'+libraryIcon('plus',16)+' Add note</button>':''}</div></div><details class="memory-history"><summary>Revision history</summary><label>View saved revision<select name="notebookRevision">${Array.from({length:this.book.revision+1},(_,i)=>`<option value="${i}" ${i===revision?'selected':''}>Revision ${i}${i===this.book.revision?' · Current':''}</option>`).reverse().join('')}</select></label></details><div class="memory-editor"></div>${this.entries.length?Object.entries(categories).map(([category,label])=>{const notes=this.entries.filter(n=>n.category===category);return notes.length?`<section class="notebook-section"><h3>${esc(label)} <span>${notes.length}</span></h3>${notes.map(n=>this.note(n,historical)).join('')}</section>`:'';}).join(''):'<div class="memory-empty">'+libraryIcon('notebook-pen',32)+'<h3>A clear place to pick up where you left off</h3><p>Capture decisions and reasons, attempts that did not work, relevant files, open questions, and the next step.</p><p>Notes help recall. Your task board and approval policy still decide what work is allowed.</p></div>'}${!historical&&this.book.nextOffset!==null?'<button type="button" data-memory="more">Load more notes</button>':''}`;
    enhanceMarkdown(el);
  }
  note(n,historical){
    const stale=n.freshness?.state==='stale';return `<article class="memory-note ${n.status!=='active'?'memory-note-closed':''}" data-note-id="${esc(n.id)}"><div class="memory-note-meta"><span class="memory-confidence confidence-${esc(n.confidence)}">${esc(n.confidence)}</span>${n.status!=='active'?`<span>${esc(n.status)}</span>`:''}${stale?'<span class="memory-stale">Source changed · recheck</span>':''}</div><div class="markdown document-markdown">${proseMarkdown(n.text)}</div>${stale?`<p class="memory-stale-reason">${esc(n.freshness.reasons.join(' · '))}</p>`:''}${n.sources?.length?`<details class="memory-sources"><summary>${n.sources.length} source${n.sources.length===1?'':'s'}</summary>${n.sources.map(s=>`<p><strong>${esc(s.kind)}</strong> <code>${esc(s.path||s.key||s.itemId||s.planId||s.reference||s.resourceId)}</code>${s.revision!==undefined?` · Revision ${s.revision}`:''}</p>`).join('')}</details>`:'<small class="memory-unlinked">No linked source</small>'}<footer><span>${esc(n.author)} · ${esc(time(n.updatedAt))}</span>${!historical?`<button type="button" data-memory="edit" data-note="${esc(n.id)}">Edit note</button>`:''}</footer></article>`;
  }
  edit(id){
    const note=id?this.entries.find(n=>n.id===id):null;this.editing=note||null;this.editRevision=this.book.revision;
    const host=this.host.querySelector('.memory-editor');host.innerHTML=`<form data-memory-form="note" class="notebook-form"><h3>${note?'Edit note':'Add a working note'}</h3><div class="memory-form-pair"><label>Category<select name="category" aria-label="Category">${options(categories,note?.category||'decision')}</select></label><label>Confidence<select name="confidence" aria-label="Confidence">${options({assumption:'Assumption',reported:'Reported',verified:'Verified by author'},note?.confidence||'assumption')}</select></label></div><label for="notebook-text">Note <span>Markdown supported</span></label><textarea id="notebook-text" name="text" rows="6" required maxlength="1800" placeholder="What matters, why, and the next useful step…">${esc(note?.text||'')}</textarea><label>Status<select name="status" aria-label="Status">${options({active:'Active',resolved:'Resolved',superseded:'Superseded'},note?.status||'active')}</select></label><label for="notebook-file">${note?.sources?.length?'Replace sources with a tracked file':'Track a file in this agent’s worktree'} <span>optional</span></label><input id="notebook-file" name="file" placeholder="src/engine.mjs"><p class="form-note">A file source is checked for changes. “Verified” is an author’s report and does not approve a task.</p><div class="dialog-actions"><button type="button" data-memory="cancel">Cancel</button><button type="submit" class="primary">Save note</button></div></form>`;host.querySelector('textarea').focus();host.scrollIntoView({block:'nearest',behavior:'smooth'});
  }
  async handleSubmit(form){
    const data=Object.fromEntries(new FormData(form)),button=form.querySelector('button[type="submit"]'),generation=this.generation;button.disabled=true;
    try{if(form.dataset.memoryForm==='note'){
      await this.api('notebook',{taskId:this.agentId,expectedRevision:this.editRevision,...(this.editing?{id:this.editing.id}:{}),category:data.category,text:data.text,confidence:data.confidence,status:data.status,...(data.file.trim()?{sources:[{kind:'file',path:data.file.trim()}]}:{})});
      if(generation!==this.generation)return;await this.load();this.feedback('Note saved. No agent was started or messaged.');
    }else{this.searchInput={query:data.query,scope:data.scope,ranking:data.ranking};const result=await this.api('memory/search?task='+encodeURIComponent(this.agentId)+'&query='+encodeURIComponent(data.query)+'&scope='+data.scope+'&ranking='+data.ranking);if(generation===this.generation)this.results(result);}}
    finally{button.disabled=false;}
  }
  results(result,append=false){
    const host=this.host.querySelector('.memory-results');if(!host)return;this.searchResult=result;
    const html=result.matches.map((m,i)=>`<article class="memory-note"><div class="memory-note-meta"><span>${esc(m.source.kind)}</span>${m.relevanceProbability!==undefined?`<span>${Math.round(m.relevanceProbability*100)}% relevance</span>`:''}${m.freshness?.state==='stale'?'<span class="memory-stale">Source changed</span>':''}${m.status?`<span>${esc(m.status)}</span>`:''}</div><h3>${esc(m.title)}</h3><pre class="memory-passage">${esc(m.text)}</pre><small>${esc(m.source.key||m.source.itemId||m.source.reference||m.source.planId||m.source.id)}${m.source.revision!==undefined?' · Revision '+m.source.revision:''}</small><button type="button" data-memory="source" data-result="${i}">Read source</button></article>`).join('')||'<div class="memory-empty">No matches in this batch. Try a task ID, file path, or a different phrase.</div>';
    host.innerHTML=`<p class="form-note">${esc(result.method)}${result.ranking?.status==='fallback'?' · Jev unavailable ('+esc(result.ranking.reason)+'); local results':result.ranking?.status==='local'?' · no AI call':result.ranking?.cacheHit?' · cached judgments':' · relevance is not verification'}${result.more?' · More matches available; narrow your query':''}</p>${html}${result.nextBefore?'<button type="button" data-memory="older">Search older context</button>':''}`;
  }
  async history(revision){if(revision===this.book.revision){delete this.historyRevision;await this.load();return;}const id=this.agentId,generation=++this.generation,result=await this.api('notebook?task='+encodeURIComponent(id)+'&revision='+revision);if(generation!==this.generation)return;this.historyRevision=revision;this.entries=result.entries;this.renderNotebook();}
  async handleClick(e){
    const b=e.target.closest('button');if(!b||!this.host.contains(b))return;
    if(b.dataset.memoryTab){this.mode=b.dataset.memoryTab;delete this.historyRevision;await this.load();return;}
    const action=b.dataset.memory;if(!action)return;
    if(action==='close')return this.onClose();if(action==='expand')return this.onExpand();if(action==='add'||action==='edit')return this.edit(b.dataset.note);if(action==='cancel'){this.host.querySelector('.memory-editor').innerHTML='';return;}
    if(action==='refresh'){delete this.historyRevision;return this.load();}
    if(action==='more'){const result=await this.api('notebook?task='+encodeURIComponent(this.agentId)+'&offset='+this.book.nextOffset);if(result.revision!==this.book.revision){await this.load();this.feedback('Notebook changed; reloaded the current revision.');return;}this.entries.push(...result.entries);this.book.nextOffset=result.nextOffset;this.renderNotebook();}
    if(action==='older')this.results(await this.api('memory/search?task='+encodeURIComponent(this.agentId)+'&query='+encodeURIComponent(this.searchInput.query)+'&scope='+this.searchInput.scope+'&ranking='+this.searchInput.ranking+'&before='+encodeURIComponent(this.searchResult.nextBefore)));
    if(action==='source'){
      const m=this.searchResult.matches[Number(b.dataset.result)];if(!m)return;
      const result=await this.api('memory/source',{taskId:this.agentId,source:m.source,offset:m.offset});
      this.host.querySelector('.memory-results').innerHTML=`<button type="button" data-memory="back-search">← Back to results</button><article class="memory-note"><h3>${esc(m.title)}</h3><div class="markdown document-markdown">${proseMarkdown(result.text)}</div>${result.nextOffset!==null?'<p class="form-note">More of this source is available.</p><button type="button" data-memory="source-more">Read next page</button>':''}</article>`;this.source={source:m.source,nextOffset:result.nextOffset,title:m.title};enhanceMarkdown(this.host.querySelector('.memory-results'));
    }
    if(action==='source-more'){const result=await this.api('memory/source',{taskId:this.agentId,source:this.source.source,offset:this.source.nextOffset});this.source.nextOffset=result.nextOffset;this.host.querySelector('.memory-results .markdown').innerHTML=proseMarkdown(result.text);if(result.nextOffset===null)b.remove();enhanceMarkdown(this.host.querySelector('.memory-results'));}
    if(action==='back-search')this.results(this.searchResult);
  }
  dispose(){this.generation++;this.host.classList.remove('memory-drawer');this.host.removeEventListener('click',this.click);this.host.removeEventListener('change',this.change);this.host.removeEventListener('submit',this.submit);}
}
